236	// The fixed starts each provider gives its keys, longer ones first. They say
237	// what kind of key it is, not which one.
238	const std::vector<std::string>& key_prefixes(const std::string& provider)
239	{
240	    static const std::vector<std::string> anthropic{"sk-ant-"};
241	    static const std::vector<std::string> openai{"sk-proj-", "sk-svcacct-", "sk-admin-", "sk-"};
242	    static const std::vector<std::string> openrouter{"sk-or-v1-", "sk-or-"};
243	    static const std::vector<std::string> none;
244	    if (provider == "anthropic")
245	        return anthropic;
246	    if (provider == "openai")
247	        return openai;
248	    if (provider == "openrouter")
249	        return openrouter;
250	    return none;
251	}
252	
253	// Keys shorter than this past their start keep their end to themselves too:
254	// 4 characters of a short key would be a large part of it.
255	constexpr std::size_t kMinHiddenForTail = 8;
256	constexpr std::size_t kTailLength       = 4;
257	constexpr const char* kEllipsis         = "\xE2\x80\xA6"; // U+2026
258	
259	} // namespace
260	
261	std::string api_key_hint(const std::string& provider, const std::string& key)
262	{
263	    std::string prefix;
264	    for (const std::string& candidate : key_prefixes(provider))
265	        if (key.size() > candidate.size() && key.compare(0, candidate.size(), candidate) == 0) {
266	            prefix = candidate;
267	            break;
268	        }
269	    std::string hint = prefix + kEllipsis;
270	    if (key.size() >= prefix.size() + kMinHiddenForTail + kTailLength)
271	        hint += key.substr(key.size() - kTailLength);
272	    return hint;
273	}
