291	bool ProviderKeySetup::start_check(const SetupCredentials& credentials)
292	{
293	    if (busy() || credentials.api_key.empty() || !setup_provider_supported(credentials.provider))
294	        return false;
295	
296	    const std::string endpoint = credentials.endpoint.empty() ? m_endpoint_override : credentials.endpoint;
297	    AgentServicePtr   candidate = make_provider_agent(*profile_for(credentials.provider), credentials.api_key, credentials.model,
298	                                                      endpoint, m_transport_factory());
299	    if (!candidate->ready())
300	        return false;
301	
302	    m_started = m_clock();
303	    if (!candidate->start(probe_request()))
304	        return false;
305	    m_candidate = std::move(candidate);
306	    return true;
307	}
