316	std::optional<SetupOutcome> ProviderKeySetup::poll()
317	{
318	    if (!m_candidate)
319	        return std::nullopt;
320	
321	    while (const std::optional<AgentEvent> event = m_candidate->poll()) {
322	        switch (event->kind) {
323	        case AgentEventKind::TextDelta:
324	            break; // What it says is irrelevant; that it answers is the test.
325	        case AgentEventKind::ToolCall:
326	        case AgentEventKind::Completed:
327	            // Either way the provider accepted the credentials and replied.
328	            return finish_ok();
329	        case AgentEventKind::Failed: {
330	            SetupOutcome outcome;
331	            outcome.error =
332	                event->error.value_or(AgentError{"setup_failed", "The provider did not answer.", true});
333	            outcome.elapsed_ms = elapsed_ms();
334	            cancel();
335	            return outcome;
336	        }
337	        }
338	    }
339	    return std::nullopt;
340	}
