370	SetupOutcome ProviderKeySetup::finish_ok()
371	{
372	    SetupOutcome outcome;
373	    outcome.ok         = true;
374	    outcome.elapsed_ms = elapsed_ms();
375	    // Drop the probe turn so the verified service is handed over idle, with
376	    // no partial response left for the user's first real message to inherit.
377	    m_candidate->cancel();
378	    outcome.service = std::move(m_candidate);
