492	AgentRuntime resolve_agent_runtime(const AgentSettings&                                         settings,
493	                                   const std::string&                                           endpoint_override,
494	                                   const std::function<std::unique_ptr<IAgentHttpTransport>()>& transport,
495	                                   ProviderListeners                                            listeners)
496	{
497	    AgentRuntime runtime;
498	    runtime.provider = settings.provider.empty() ? "openai" : settings.provider;
499	    if (!settings.enabled) {
500	        runtime.unavailable_reason = "The Agent is not enabled.";
501	        return runtime;
502	    }
503	    const ProviderProfile* profile = profile_for(runtime.provider);
504	    if (profile == nullptr) {
505	        runtime.unavailable_reason = "The configured Agent provider is not supported.";
506	        return runtime;
507	    }
508	    if (!settings.cloud_consent) {
509	        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
510	        return runtime;
511	    }
512	    if (settings.api_key.empty()) {
513	        runtime.unavailable_reason = "No " + profile->display_name + " API key is configured.";
514	        return runtime;
515	    }
516	    runtime.service = make_provider_agent(*profile, settings.api_key, settings.model, endpoint_override, transport(),
517	                                          std::move(listeners));
518	    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
519	    if (runtime.availability == AgentAvailability::Unavailable)
520	        runtime.unavailable_reason = "The " + profile->display_name + " Agent could not be initialized.";
521	    return runtime;
522	}
