634	AgentSetupServicePtr make_agent_setup(AppConfig* config)
635	{
636	    // Committing is the only part of setup that touches the machine, so it
637	    // lives here rather than in the GUI-free probe. Reaching this point means
638	    // the user read what the dock says about the provider billing them and
639	    // about the key staying on this machine, and chose to continue: that is
640	    // the cloud consent load_agent_runtime() requires on the next launch.
641	    auto commit = [config](const SetupCredentials& credentials) {
642	        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
643	            return false;
644	        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
645	        config->set(kSection, "provider", credentials.provider);
646	        config->set(kSection, "enabled", "true");
647	        config->set(kSection, "cloud_consent", "true");
648	        if (!credentials.model.empty())
649	            config->set(kSection, "model", credentials.model);
650	        // Written now, not at the next routine save, so a crash after setup
651	        // does not lose a key the user was just told is stored.
652	        config->save();
653	        return true;
654	    };
655	    ProviderKeySetup::KeyStore keys;
656	    keys.load   = [config](const std::string& provider) { return load_provider_api_key(config, provider); };
657	    keys.remove = [config](const std::string& provider) {
658	        if (config == nullptr || load_provider_api_key(config, provider).empty())
659	            return false;
660	        config->erase(kSection, api_key_item_for(provider));
661	        // A chat without a choice of its own talks to the recorded provider;
662	        // once its key is gone, that is the first provider that still has one.
663	        if (config->get(kSection, "provider") == provider)
664	            for (const ProviderProfile& profile : provider_profiles())
665	                if (!load_provider_api_key(config, profile.id).empty()) {
666	                    config->set(kSection, "provider", profile.id);
667	                    break;
668	                }
669	        // Saved now, as a stored key is: the person was just told it is gone.
670	        config->save();
671	        return true;
672	    };
673	    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit), std::move(keys),
674	                                              agent_endpoint_override());
675	}
