#pragma once

// Signing in to a JusPrin account, which is how the "jusprin" provider gets
// its credential: an OAuth2 access token from the JusPrin server, used as the
// gateway's bearer token where another provider takes an API key.
//
// Sign-in is the authorization code flow with PKCE in the system browser,
// answered on a loopback port (RFC 8252); the server accepts any port on its
// http://127.0.0.1/callback redirect. Finishing a sign-in, and checking a
// token the app already holds (one imported from JusPrin v1, or the stored
// one), are the same step: ask the server who the account is and which
// models it serves this account, in which wire format. A token that passes
// that step is stored with the answers, and the agent built from it is handed
// over the way key setup hands over its verified agent.
//
// GUI-free and poll-driven like ProviderKeySetup: the browser, the loopback
// server and HTTP are injected, their callbacks may arrive on any thread and
// only queue, and outcomes are released from poll() on the owner's thread.

#include "AgentService.hpp"
#include "ModelCatalog.hpp"

#include <functional>
#include <memory>
#include <mutex>
#include <optional>
#include <string>
#include <utility>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

// The application JusPrin 2 is registered as on every JusPrin server
// (obico-server's README_jusprin_server.md says how a self-hosted server
// adds it): a public client using the authorization code grant.
inline constexpr const char* kCloudClientId = "JusPrin2";
// The loopback port the browser is sent back to. Fixed, because OrcaSlicer's
// loopback server takes a port, not one the system picks; any port is
// accepted by the server.
inline constexpr unsigned short kCloudCallbackPort = 41172;

struct CloudAuthorization
{
    std::string    authorize_url; // the page the browser opens
    std::string    token_url;
    std::string    client_id;
    std::string    redirect_uri;
    std::string    scope;
    std::string    state;
    std::string    code_verifier;
    unsigned short port{0};
    // Where the browser is sent once the app has the token, or failed to get it.
    std::string    success_url;
    std::string    failure_url;
};

struct CloudAuthorizationResult
{
    bool        ok{false};
    std::string access_token;
    std::string error; // for the log; the page shows its own words
};

struct CloudHttpResult
{
    unsigned    status{0}; // 0 when the request never got an answer
    std::string body;
};

// What signing in needs from the machine.
struct CloudAccountDeps
{
    // Opens the browser on the authorize page and waits for its redirect on
    // the loopback port; `done` is called once, with the token exchange's
    // result. False when the loopback port could not be opened.
    std::function<bool(const CloudAuthorization&, std::function<void(CloudAuthorizationResult)> done)> authorize;
    // Stops waiting; `done` is then not called.
    std::function<void()> cancel_authorize;
    // A GET with the token as bearer; `done` is called once.
    std::function<void(const std::string& url, const std::string& token, std::function<void(CloudHttpResult)> done)> get;
    // Revokes a token on the server, best effort: nothing waits for it.
    std::function<void(const std::string& url, const std::string& client_id, const std::string& token)> revoke;
    // A PKCE verifier, its S256 challenge and a state value, fresh each call.
    std::function<void(std::string& verifier, std::string& challenge, std::string& state)> pkce;
};

// The account as JusPrin keeps it on this computer.
struct CloudAccountRecord
{
    std::string token;
    std::string email;
    // Each model the account was last told about, with its wire format.
    std::vector<std::pair<std::string, std::string>> formats;
};

// Where the account is kept, injected so this file never reaches AppConfig.
struct CloudAccountStore
{
    std::function<std::optional<CloudAccountRecord>()> load;
    // Stores a verified account and records the choices that make it the
    // Agent's provider. False when it could not be written.
    std::function<bool(const CloudAccountRecord&)> save;
    std::function<bool()> erase;
};

enum class CloudSignInPhase { Idle, Browser, Checking };

struct CloudSignInOutcome
{
    enum class Kind { SignedIn, Expired, Failed };
    Kind            kind{Kind::Failed};
    std::string     email;
    // SignedIn: whether the account could be stored on this computer.
    bool            saved{false};
    // SignedIn: the agent for the account's default model, idle.
    AgentServicePtr service;
    // Failed: what went wrong.
    AgentError      error;
};

class ICloudSignIn
{
public:
    virtual ~ICloudSignIn() = default;

    virtual CloudSignInPhase phase() const = 0;
    // The page the browser was sent to, while the phase is Browser, for a
    // person whose browser did not open.
    virtual std::string browser_url() const = 0;

    // Opens the browser. False while a sign-in or check is running, or when
    // the loopback port could not be opened.
    virtual bool start() = 0;
    // Checks the token already stored: the account's email and model formats
    // are refreshed, or the token turns out to have expired. False when no
    // token is stored or something is already running.
    virtual bool check_stored() = 0;
    virtual void cancel() = 0;
    virtual std::optional<CloudSignInOutcome> poll() = 0;

    // The stored account, or nothing when signed out.
    virtual std::optional<CloudAccountRecord> account() const = 0;
    // Forgets the account on this computer and revokes its token. False when
    // there was none or it could not be removed.
    virtual bool sign_out() = 0;
};

using CloudSignInPtr = std::shared_ptr<ICloudSignIn>;

class CloudSignIn final : public ICloudSignIn
{
public:
    // Builds the agent for a verified account: its token, the model and that
    // model's wire format.
    using AgentFactory = std::function<AgentServicePtr(const std::string& token, const std::string& model,
                                                       const std::string& format)>;

    // `server` is the JusPrin server's base URL, as "https://app.obico.io";
    // `gateway` is the provider's request endpoint, whose sibling "models"
    // lists the account's models.
    CloudSignIn(std::string server, std::string gateway, std::string default_model, CloudAccountDeps deps,
                CloudAccountStore store, AgentFactory agents);
    ~CloudSignIn() override;

    CloudSignInPhase                  phase() const override { return m_phase; }
    std::string                       browser_url() const override;
    bool                              start() override;
    bool                              check_stored() override;
    void                              cancel() override;
    std::optional<CloudSignInOutcome> poll() override;
    std::optional<CloudAccountRecord> account() const override;
    bool                              sign_out() override;

private:
    struct Inbox;

    void begin_check(std::string token);
    void ask_who(std::uint64_t generation);
    void ask_models(std::uint64_t generation);
    std::optional<CloudSignInOutcome> finish_check();
    CloudSignInOutcome failed(const std::string& code, const std::string& message, bool retryable);

    std::string                    m_server;
    std::string                    m_gateway;
    std::string                    m_default_model;
    CloudAccountDeps               m_deps;
    CloudAccountStore              m_store;
    AgentFactory                   m_agents;
    std::shared_ptr<Inbox>         m_inbox;
    CloudSignInPhase               m_phase{CloudSignInPhase::Idle};
    std::uint64_t                  m_generation{0};
    CloudAuthorization             m_authorization;
    // The check in progress: the token being checked, and what the server
    // has said so far.
    std::string                    m_token;
    std::optional<CloudHttpResult> m_who;
    std::optional<CloudHttpResult> m_models;
};

// The JusPrin server a token comes from and goes back to, from its gateway
// endpoint: everything before "/ent/".
std::string cloud_server_from_gateway(const std::string& gateway);

} // namespace Slic3r::GUI::JusPrin::Agent

#include "CloudAccount.hpp"

#include <nlohmann/json.hpp>

#include <cstdio>
#include <deque>

namespace Slic3r::GUI::JusPrin::Agent {

using nlohmann::json;

namespace {

std::string percent_encoded(const std::string& text)
{
    std::string encoded;
    for (const unsigned char c : text) {
        if (std::isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
            encoded += static_cast<char>(c);
        } else {
            char escaped[4];
            std::snprintf(escaped, sizeof(escaped), "%%%02X", c);
            encoded += escaped;
        }
    }
    return encoded;
}

std::string query(const std::vector<std::pair<std::string, std::string>>& parameters)
{
    std::string text;
    for (const auto& [name, value] : parameters)
        text += (text.empty() ? "" : "&") + name + "=" + percent_encoded(value);
    return text;
}

bool refused(const CloudHttpResult& result) { return result.status == 401 || result.status == 403; }

} // namespace

// What the injected browser and HTTP calls report, queued until poll(). Shared
// with the callbacks so one that arrives after this object is gone has
// somewhere harmless to go.
struct CloudSignIn::Inbox
{
    enum class Kind { Authorized, Who, Models };
    struct Item
    {
        std::uint64_t            generation{0};
        Kind                     kind{Kind::Authorized};
        CloudAuthorizationResult authorization;
        CloudHttpResult          http;
    };
    std::mutex       mutex;
    std::deque<Item> items;

    void push(Item item)
    {
        std::lock_guard<std::mutex> lock(mutex);
        items.push_back(std::move(item));
    }
    std::optional<Item> pop()
    {
        std::lock_guard<std::mutex> lock(mutex);
        if (items.empty())
            return std::nullopt;
        Item item = std::move(items.front());
        items.pop_front();
        return item;
    }
};

std::string cloud_server_from_gateway(const std::string& gateway)
{
    const std::size_t ent = gateway.find("/ent/");
    if (ent != std::string::npos)
        return gateway.substr(0, ent);
    const std::size_t scheme = gateway.find("://");
    const std::size_t path   = gateway.find('/', scheme == std::string::npos ? 0 : scheme + 3);
    return path == std::string::npos ? gateway : gateway.substr(0, path);
}

CloudSignIn::CloudSignIn(std::string server, std::string gateway, std::string default_model, CloudAccountDeps deps,
                         CloudAccountStore store, AgentFactory agents)
    : m_server(std::move(server)), m_gateway(std::move(gateway)), m_default_model(std::move(default_model)),
      m_deps(std::move(deps)), m_store(std::move(store)), m_agents(std::move(agents)), m_inbox(std::make_shared<Inbox>())
{}

CloudSignIn::~CloudSignIn() { cancel(); }

std::string CloudSignIn::browser_url() const
{
    return m_phase == CloudSignInPhase::Browser ? m_authorization.authorize_url : std::string();
}

bool CloudSignIn::start()
{
    if (m_phase != CloudSignInPhase::Idle)
        return false;
    std::string verifier, challenge, state;
    m_deps.pkce(verifier, challenge, state);
    CloudAuthorization authorization;
    authorization.client_id     = kCloudClientId;
    authorization.port          = kCloudCallbackPort;
    authorization.redirect_uri  = "http://127.0.0.1:" + std::to_string(kCloudCallbackPort) + "/callback";
    authorization.scope         = "read write";
    authorization.state         = state;
    authorization.code_verifier = verifier;
    authorization.token_url     = m_server + "/o/token/";
    authorization.success_url   = m_server + "/ent/jusprin/v2/signed_in/";
    authorization.failure_url   = m_server + "/ent/jusprin/v2/sign_in_failed/";
    authorization.authorize_url = m_server + "/o/authorize/?" +
                                  query({{"response_type", "code"},
                                         {"client_id", authorization.client_id},
                                         {"redirect_uri", authorization.redirect_uri},
                                         {"scope", authorization.scope},
                                         {"state", state},
                                         {"code_challenge", challenge},
                                         {"code_challenge_method", "S256"}});

    const std::uint64_t generation = ++m_generation;
    std::weak_ptr<Inbox> inbox     = m_inbox;
    if (!m_deps.authorize(authorization, [inbox, generation](CloudAuthorizationResult result) {
            if (const auto target = inbox.lock())
                target->push({generation, Inbox::Kind::Authorized, std::move(result), {}});
        }))
        return false;
    m_authorization = std::move(authorization);
    m_phase         = CloudSignInPhase::Browser;
    return true;
}

bool CloudSignIn::check_stored()
{
    if (m_phase != CloudSignInPhase::Idle || !m_store.load)
        return false;
    const std::optional<CloudAccountRecord> record = m_store.load();
    if (!record || record->token.empty())
        return false;
    ++m_generation;
    begin_check(record->token);
    return true;
}

void CloudSignIn::begin_check(std::string token)
{
    m_phase = CloudSignInPhase::Checking;
    m_token = std::move(token);
    m_who.reset();
    m_models.reset();
    ask_who(m_generation);
    ask_models(m_generation);
}

void CloudSignIn::ask_who(std::uint64_t generation)
{
    std::weak_ptr<Inbox> inbox = m_inbox;
    m_deps.get(m_server + "/jusprin/api/me/", m_token, [inbox, generation](CloudHttpResult result) {
        if (const auto target = inbox.lock())
            target->push({generation, Inbox::Kind::Who, {}, std::move(result)});
    });
}

void CloudSignIn::ask_models(std::uint64_t generation)
{
    const std::size_t    slash = m_gateway.rfind('/');
    const std::string    url   = (slash == std::string::npos ? m_gateway : m_gateway.substr(0, slash)) + "/models";
    std::weak_ptr<Inbox> inbox = m_inbox;
    m_deps.get(url, m_token, [inbox, generation](CloudHttpResult result) {
        if (const auto target = inbox.lock())
            target->push({generation, Inbox::Kind::Models, {}, std::move(result)});
    });
}

void CloudSignIn::cancel()
{
    if (m_phase == CloudSignInPhase::Browser && m_deps.cancel_authorize)
        m_deps.cancel_authorize();
    ++m_generation;
    m_phase = CloudSignInPhase::Idle;
    m_token.clear();
    m_who.reset();
    m_models.reset();
}

std::optional<CloudSignInOutcome> CloudSignIn::poll()
{
    while (std::optional<Inbox::Item> item = m_inbox->pop()) {
        if (item->generation != m_generation)
            continue; // from a sign-in that was cancelled
        switch (item->kind) {
        case Inbox::Kind::Authorized:
            if (m_phase != CloudSignInPhase::Browser)
                continue;
            if (!item->authorization.ok || item->authorization.access_token.empty())
                return failed("sign_in_failed", "Signing in didn't finish. Nothing was saved. Try again.", true);
            begin_check(std::move(item->authorization.access_token));
            break;
        case Inbox::Kind::Who: m_who = std::move(item->http); break;
        case Inbox::Kind::Models: m_models = std::move(item->http); break;
        }
        if (m_phase == CloudSignInPhase::Checking && m_who && m_models)
            return finish_check();
    }
    return std::nullopt;
}

std::optional<CloudSignInOutcome> CloudSignIn::finish_check()
{
    const CloudHttpResult who    = std::move(*m_who);
    const CloudHttpResult models = std::move(*m_models);
    m_who.reset();
    m_models.reset();
    if (refused(who) || refused(models)) {
        m_phase = CloudSignInPhase::Idle;
        m_token.clear();
        CloudSignInOutcome outcome;
        outcome.kind = CloudSignInOutcome::Kind::Expired;
        return outcome;
    }
    const json who_json    = json::parse(who.body, nullptr, false);
    const json models_json = json::parse(models.body, nullptr, false);
    if (who.status != 200 || models.status != 200 || !who_json.is_object() || !models_json.is_object() ||
        !models_json.contains("data"))
        return failed("account_unreachable", "JusPrin couldn't be reached to finish signing in. Try again.", true);

    CloudAccountRecord record;
    record.token = m_token;
    record.email = who_json.value("email", "");
    std::string model, format;
    for (const json& entry : models_json["data"]) {
        const std::string id = entry.value("id", ""), entry_format = entry.value("format", "");
        if (id.empty() || entry_format.empty())
            continue;
        record.formats.emplace_back(id, entry_format);
        // The provider's default model, or else the first the server lists.
        if (model.empty() || id == m_default_model) {
            if (model != m_default_model) {
                model  = id;
                format = entry_format;
            }
        }
    }
    AgentServicePtr service = model.empty() ? nullptr : m_agents(m_token, model, format);
    if (!service)
        return failed("account_no_models", "JusPrin has no Agent model for this account right now. Try again later.", true);

    CloudSignInOutcome outcome;
    outcome.kind    = CloudSignInOutcome::Kind::SignedIn;
    outcome.email   = record.email;
    outcome.saved   = m_store.save && m_store.save(record);
    outcome.service = std::move(service);
    m_phase         = CloudSignInPhase::Idle;
    m_token.clear();
    return outcome;
}

CloudSignInOutcome CloudSignIn::failed(const std::string& code, const std::string& message, bool retryable)
{
    m_phase = CloudSignInPhase::Idle;
    m_token.clear();
    CloudSignInOutcome outcome;
    outcome.kind  = CloudSignInOutcome::Kind::Failed;
    outcome.error = AgentError{code, message, retryable};
    return outcome;
}

std::optional<CloudAccountRecord> CloudSignIn::account() const
{
    if (!m_store.load)
        return std::nullopt;
    std::optional<CloudAccountRecord> record = m_store.load();
    if (!record || record->token.empty())
        return std::nullopt;
    return record;
}

bool CloudSignIn::sign_out()
{
    const std::optional<CloudAccountRecord> record = account();
    if (!record || !m_store.erase || !m_store.erase())
        return false;
    cancel();
    if (m_deps.revoke)
        m_deps.revoke(m_server + "/o/revoke_token/", kCloudClientId, record->token);
    return true;
}

} // namespace Slic3r::GUI::JusPrin::Agent

